import{_ as e,f as s,o,av as n}from"./chunks/framework.CDywcT2R.js";const h=JSON.parse('{"title":"加密解密","description":"","frontmatter":{},"headers":[],"relativePath":"zh_CN/security/encryption.md","filePath":"zh_CN/security/encryption.md","lastUpdated":1789666050000}'),r={name:"zh_CN/security/encryption.md"};function l(c,a,t,p,d,i){return o(),s("div",null,a[0]||(a[0]=[n('<h1 id="加密解密" tabindex="-1">加密解密 <a class="header-anchor" href="#加密解密" aria-label="Permalink to “加密解密”">​</a></h1><h2 id="简介" tabindex="-1">简介 <a class="header-anchor" href="#简介" aria-label="Permalink to “简介”">​</a></h2><p>Goravel 的加密机制使用的是 OpenSSL 所提供的 AES-256 加密。 所有 Goravel 加密之后的结果都会使用消息认证码 (GMAC) 签名，使其底层值不能在加密后再次修改。</p><h2 id="配置" tabindex="-1">配置 <a class="header-anchor" href="#配置" aria-label="Permalink to “配置”">​</a></h2><p>在使用 Goravel 的加密工具之前，你必须先设置 <code>config/app.go</code> 配置文件中的 <code>key</code> 配置项。 该配置项由环境变量 <code>APP_KEY</code> 设定。 使用 <code>./artisan key:generate</code> 命令来生成此配置的值，因为 <code>key:generate</code> 命令将利用 Golang 的安全随机字节生成器为你的应用程序创建安全的加密密钥。</p><h2 id="基本用法" tabindex="-1">基本用法 <a class="header-anchor" href="#基本用法" aria-label="Permalink to “基本用法”">​</a></h2><h3 id="加密一个值" tabindex="-1">加密一个值 <a class="header-anchor" href="#加密一个值" aria-label="Permalink to “加密一个值”">​</a></h3><p>你可以使用 <code>facades.Crypt()</code> 提供的 <code>EncryptString</code> 来加密一个值。 所有加密的值都使用 OpenSSL 的 <code>AES-256-GCM</code> 来进行加密。 此外，所有加密过的值都会使用消息认证码 (GMAC) 来签名，以检测加密字符串是否被篡改过。</p><div class="language-go line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">go</span><pre class="shiki goravel vp-code" style="background-color:#00000000;color:#101820;" tabindex="0"><code><span class="line"><span style="color:#101820;">secret</span><span style="color:#68747D;">,</span><span style="color:#101820;"> err </span><span style="color:#68747D;">:=</span><span style="color:#101820;"> facades</span><span style="color:#68747D;">.</span><span style="color:#0077B3;">Crypt</span><span style="color:#68747D;">().</span><span style="color:#0077B3;">EncryptString</span><span style="color:#68747D;">(</span><span style="color:#68747D;">&quot;goravel&quot;</span><span style="color:#68747D;">)</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><h3 id="解密一个值" tabindex="-1">解密一个值 <a class="header-anchor" href="#解密一个值" aria-label="Permalink to “解密一个值”">​</a></h3><p>你可以使用 <code>facades.Crypt()</code> 提供的 <code>DecryptString</code> 来进行解密。 如果该值不能被正确解密，例如消息认证码 (MAC) 无效，会返回错误。</p><div class="language-go line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">go</span><pre class="shiki goravel vp-code" style="background-color:#00000000;color:#101820;" tabindex="0"><code><span class="line"><span style="color:#101820;">str</span><span style="color:#68747D;">,</span><span style="color:#101820;"> err </span><span style="color:#68747D;">:=</span><span style="color:#101820;"> facades</span><span style="color:#68747D;">.</span><span style="color:#0077B3;">Crypt</span><span style="color:#68747D;">().</span><span style="color:#0077B3;">DecryptString</span><span style="color:#68747D;">(</span><span style="color:#101820;">secret</span><span style="color:#68747D;">)</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div>',12)]))}const b=e(r,[["render",l]]);export{h as __pageData,b as default};
